import base64
import json
import mimetypes
import os
from pathlib import Path
from typing import Any, Dict, List, Optional, Union

import boto3


def _read_input_document(document: Union[str, bytes, bytearray, Path]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    path = Path(document)
    return path.read_bytes()


def _guess_mime_type(document: Union[str, bytes, bytearray, Path], default: str = "application/octet-stream") -> str:
    if isinstance(document, (str, Path)):
        mime, _ = mimetypes.guess_type(str(document))
        if mime:
            return mime
    return default


def _extract_text_from_blocks(blocks: List[Dict[str, Any]]) -> str:
    words = []
    block_map = {b.get("Id"): b for b in blocks if b.get("Id")}
    for block in blocks:
        if block.get("BlockType") == "LINE" and block.get("Text"):
            words.append(block["Text"])
    if words:
        return "\n".join(words)

    # Fallback: reconstruct from WORD relationships when LINE blocks are absent.
    lines = []
    for block in blocks:
        if block.get("BlockType") == "LINE" and block.get("Relationships"):
            line_words = []
            for rel in block.get("Relationships", []):
                if rel.get("Type") == "CHILD":
                    for child_id in rel.get("Ids", []):
                        child = block_map.get(child_id)
                        if child and child.get("BlockType") == "WORD" and child.get("Text"):
                            line_words.append(child["Text"])
            if line_words:
                lines.append(" ".join(line_words))
    return "\n".join(lines)


def _extract_kv_pairs_from_blocks(blocks: List[Dict[str, Any]]) -> Dict[str, Any]:
    block_map = {b.get("Id"): b for b in blocks if b.get("Id")}
    keys = [b for b in blocks if b.get("BlockType") == "KEY_VALUE_SET" and "KEY" in b.get("EntityTypes", [])]
    values = [b for b in blocks if b.get("BlockType") == "KEY_VALUE_SET" and "VALUE" in b.get("EntityTypes", [])]

    value_by_id: Dict[str, str] = {}

    def block_text(block_id: str) -> str:
        block = block_map.get(block_id)
        if not block:
            return ""
        text_parts = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []):
                    child = block_map.get(child_id)
                    if child and child.get("Text"):
                        text_parts.append(child["Text"])
        return " ".join(text_parts).strip()

    for value_block in values:
        value_text = block_text(value_block["Id"])
        if value_text:
            value_by_id[value_block["Id"]] = value_text

    result: Dict[str, Any] = {}
    for key_block in keys:
        key_text = block_text(key_block["Id"])
        if not key_text:
            continue

        assigned_value = ""
        for rel in key_block.get("Relationships", []):
            if rel.get("Type") == "VALUE":
                for value_id in rel.get("Ids", []):
                    assigned_value = value_by_id.get(value_id, block_text(value_id))
                    if assigned_value:
                        break
            if assigned_value:
                break

        result[key_text] = assigned_value if assigned_value else None

    return result


def extract_key_value_pairs(
    document: Union[str, bytes, bytearray, Path],
    *,
    aws_region: Optional[str] = None,
    feature_types: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Extract key-value pairs from a form-like document using Amazon Textract.

    Args:
        document: Path to a local file or raw bytes.
        aws_region: AWS region for Textract. Defaults to AWS_REGION/AWS_DEFAULT_REGION/us-east-1.
        feature_types: Reserved for analyze_document; defaults to ["FORMS"].

    Returns:
        Dict containing:
          - key_values: extracted key-value pairs
          - text: full OCR text
          - provider: provider identifier
    """
    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    client = boto3.client("textract", region_name=region)
    data = _read_input_document(document)
    mime_type = _guess_mime_type(document)

    if mime_type.startswith("image/"):
        response = client.analyze_document(
            Document={"Bytes": data},
            FeatureTypes=feature_types or ["FORMS"],
        )
    else:
        # Textract AnalyzeDocument supports images and certain PDFs via async APIs.
        # For a synchronous one-shot interface, fall back to detect_document_text for non-images.
        response = client.detect_document_text(
            Document={"Bytes": data},
        )

    blocks = response.get("Blocks", [])
    key_values = _extract_kv_pairs_from_blocks(blocks) if blocks else {}
    text = _extract_text_from_blocks(blocks) if blocks else ""

    return {
        "provider": "amazon-textract",
        "key_values": key_values,
        "text": text,
        "raw_response": response,
    }
